"""Differential fuzz: new pipeline vs the original (pre-refactor) implementations."""
import copy, csv, io, json, random, sys
sys.path.insert(0, "/workspace")
from src.csv_exporter import export_csv
from src.exporter import export_rows
from src.dispatcher import export
from src.json_exporter import export_json


def ref_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["id", "name"])
    for row in rows:
        clean = ["" if row.get(key) is None else str(row[key]) for key in ("id", "name")]
        writer.writerow(clean)
    return buffer.getvalue()


def ref_json(rows):
    clean = []
    for row in rows:
        clean.append({key: "" if row.get(key) is None else str(row[key]) for key in ("id", "name")})
    return json.dumps(clean, ensure_ascii=False, separators=(",", ":"))


random.seed(0)
ALPHABET = 'ab",\'\n\r\t xé日本0'


def rand_value():
    r = random.random()
    if r < 0.15:
        return None
    if r < 0.30:
        return random.choice([0, 1, -5, 2.5, True, False, 10**20, 1e-7])
    if r < 0.40:
        return ""
    if r < 0.45:
        return []
    return "".join(random.choice(ALPHABET) for _ in range(random.randint(0, 6)))


def rand_row():
    row = {}
    for key in ("id", "name", "extra"):
        if random.random() < 0.8:
            row[key] = rand_value()
    if random.random() < 0.5:
        row = dict(reversed(list(row.items())))
    return row


for i in range(3000):
    rows = [rand_row() for _ in range(random.randint(0, 5))]
    for fmt, new_fn, ref_fn in (("csv", export_csv, ref_csv), ("json", export_json, ref_json)):
        a = new_fn(copy.deepcopy(rows))
        b = ref_fn(copy.deepcopy(rows))
        assert a == b, (fmt, i, rows, a, b)
    assert export(copy.deepcopy(rows), "csv") == ref_csv(copy.deepcopy(rows))
    assert export(copy.deepcopy(rows), "json") == ref_json(copy.deepcopy(rows))
    assert export_rows(copy.deepcopy(rows), "csv") == ref_csv(copy.deepcopy(rows))
    assert export_rows(copy.deepcopy(rows), "json") == ref_json(copy.deepcopy(rows))

# generators
rows = [rand_row() for _ in range(4)]
assert export_csv((r for r in rows)) == ref_csv(copy.deepcopy(rows))
assert export_json((r for r in rows)) == ref_json(copy.deepcopy(rows))
assert export((r for r in rows), "csv") == ref_csv(copy.deepcopy(rows))

# error parity
for bad in ("xml", "", 7, None, b"csv"):
    for fn, args in ((export, (rows, bad)), (export_rows, (rows, bad))):
        try:
            fn(*args)
        except ValueError as err:
            assert str(err) == "unsupported format", (bad, str(err))
        except Exception as err:
            raise AssertionError((bad, err))
        else:
            raise AssertionError((bad, "no error"))
print("fuzz OK: 3000 random row sets matched the original behavior exactly")
PY
